+  if (abs >= 1e9) return `${(amount / 1e9).toFixed(2)}B`;
+  if (abs >= 1e6) return `${(amount / 1e6).toFixed(2)}M`;
+  if (abs >= 1e3) return `${(amount / 1e3).toFixed(2)}K`;
