+function seededSpark(seed) {
+  const rnd = mulberry32(seed);
+  const points = [];
+  let v = rnd() * 0.4 + 0.25;
+  for (let i = 0; i < 7; i++) {
+    v += (rnd() - 0.5) * 0.18;
+    v = clamp(v, 0.1, 0.95);
+    points.push(v);
+  }
+  return points;
+}
