+  const pages = new Set([1, 2, 3, 4, TOTAL_PAGES, currentPage, currentPage - 1, currentPage + 1]);
+  const list = Array.from(pages)
+    .filter((p) => p >= 1 && p <= TOTAL_PAGES)
