+    network: 'All Networks',
+    page: 1,
+    sortKey: 'marketCap',
+    sortDir: -1,
+    filters: { search: '', change24h: 'all', minMarketCap: null },
+  };
+
+  setupPromoCarousel();
+  setupMarketAccordion();
+  setupPanels();
+  setupTabs(state);
+  setupSortPills(state);
+  setupSorting(state);
+  setupFilters(state);
+  setupColumnToggles(state);
+  setupPagination(state);
+
+  renderTable(state);
+}
+
+document.addEventListener('DOMContentLoaded', main);
